import Papa from 'papaparse'
import csv from '../../data/field_master_2026.csv?raw'
import type { FieldRow } from './types'

// Field Master 2026 (Drive: AI/AI Data, generated by build_context_tables.py), bundled so the field
// board has every field even before the hub is connected. The hub's cc.field table is the live copy.

export const FIELD_MASTER_SOURCE = 'Field Master 2026.csv'
export const FIELD_MASTER_URL = 'https://drive.google.com/file/d/181wSjmMcoy_lwkruFOaNGGmesrHCvyY0/view'

export function parseFieldMaster(text: string, year = 2026): FieldRow[] {
  const { data } = Papa.parse<Record<string, string>>(text.replace(/^﻿/, ''), { header: true, skipEmptyLines: true })
  return data.map((r) => ({
    id: `${year}|${r['Field'].trim()}`,
    cropYear: year,
    farm: r['Farm'].trim(),
    name: r['Field'].trim(),
    crop: r[`${year} Crop`].trim(),
    water: r['Water'].trim() === 'Dryland' ? 'Dryland' : 'Irrigated',
    plannedAcres: Number(r['Planned Acres']) || 0,
    producer: r['Producer (FSA)']?.trim() || null,
    fsn: r['FSN']?.trim() || null,
    county: r['County']?.trim() || null,
  }))
}

export const FIELD_MASTER: FieldRow[] = parseFieldMaster(csv)
